-- Применение: make ch-sql FILE=sql/gold_dashboard_manual_series_catalog.sql
-- Идемпотентность: ReplacingMergeTree по (source, series) — повторный прогон перезапишет строки.
-- Значения рядов пишутся НЕ здесь, а через ingest-endpoint POST /v1/manual_series (source = 'manual').

